SET NAMES utf8mb4;

-- 0、清理上一次生成的演示数据
DELETE FROM `food_comment`  WHERE `food_id` >= 200;
DELETE FROM `food_like`     WHERE `food_id` >= 200;
DELETE FROM `food_favorite` WHERE `food_id` >= 200;
DELETE FROM `food_info`     WHERE `id` >= 200;
-- 分类使用固定 ID，先删后插保证可重复执行
DELETE FROM `food_category` WHERE `id` BETWEEN 100 AND 111;

