-- 8、计数与明细保持一致
UPDATE `food_info` fi SET
  fi.`like_count`     = (SELECT COUNT(1) FROM `food_like`     fl WHERE fl.`food_id` = fi.`id`),
  fi.`favorite_count` = (SELECT COUNT(1) FROM `food_favorite` ff WHERE ff.`food_id` = fi.`id`),
  fi.`comment_count`  = (SELECT COUNT(1) FROM `food_comment`  fc WHERE fc.`food_id` = fi.`id`);

-- 9、校验
SELECT '分类数' AS `检查项`, COUNT(1) AS `结果` FROM `food_category`
UNION ALL SELECT '美食数', COUNT(1) FROM `food_info`
UNION ALL SELECT '演示用户数', COUNT(1) FROM `sys_user` WHERE `user_id` > 100
UNION ALL SELECT '发布者数量', COUNT(DISTINCT `create_by`) FROM `food_info`
UNION ALL SELECT '点赞数', COUNT(1) FROM `food_like`
UNION ALL SELECT '收藏数', COUNT(1) FROM `food_favorite`
UNION ALL SELECT '评论数', COUNT(1) FROM `food_comment`
UNION ALL SELECT '无封面美食', COUNT(1) FROM `food_info` WHERE `image` = '' OR `image` IS NULL;
