INSERT INTO `food_info` (`id`,`category_id`,`title`,`image`,`description`,`content`,`like_count`,`favorite_count`,`comment_count`,`status`,`create_by`,`create_time`,`remark`) VALUES (200, 100, '麻婆豆腐', '/profile/upload/seed/dish_ad19ef128cd3.jpg', '麻辣鲜香，下饭神器', '豆腐嫩滑、牛肉臊子酥香，一勺红油盖住整碗米饭。\n\n小贴士：食材提前备齐，火候宁小勿大，出锅前再调味。', 128, 56, 0, '0', 'admin', date_sub(sysdate(), interval 20 day), '');
INSERT INTO `food_info` (`id`,`category_id`,`title`,`image`,`description`,`content`,`like_count`,`favorite_count`,`comment_count`,`status`,`create_by`,`create_time`,`remark`) VALUES (201, 100, '宫保鸡丁', '/profile/upload/seed/dish_268ca7407944.jpg', '酸甜微辣，鸡肉嫩滑', '鸡丁滑嫩、花生酥脆，糖醋汁收得亮亮的。\n\n小贴士：食材提前备齐，火候宁小勿大，出锅前再调味。', 96, 40, 0, '0', 'admin', date_sub(sysdate(), interval 21 day), '');
INSERT INTO `food_info` (`id`,`category_id`,`title`,`image`,`description`,`content`,`like_count`,`favorite_count`,`comment_count`,`status`,`create_by`,`create_time`,`remark`) VALUES (202, 100, '回锅肉', '/profile/upload/seed/dish_e4e758f6e2e2.jpg', '肥而不腻，川菜之首', '二刀肉先煮后炒，郫县豆瓣炒出红油，蒜苗一拌香气冲鼻。\n\n小贴士：食材提前备齐，火候宁小勿大，出锅前再调味。', 142, 61, 0, '0', 'chuancai', date_sub(sysdate(), interval 22 day), '');
INSERT INTO `food_info` (`id`,`category_id`,`title`,`image`,`description`,`content`,`like_count`,`favorite_count`,`comment_count`,`status`,`create_by`,`create_time`,`remark`) VALUES (203, 100, '水煮鱼', '/profile/upload/seed/dish_b9f6aa0564e5.jpg', '麻辣鲜烫，鱼片嫩滑', '鱼片薄而不断，热油泼在花椒辣椒上的一瞬间最香。\n\n小贴士：食材提前备齐，火候宁小勿大，出锅前再调味。', 167, 72, 0, '0', 'chuancai', date_sub(sysdate(), interval 23 day), '');
